rollback.sql:
DO $$
DECLARE
    tenant_table RECORD;
BEGIN
    FOR tenant_table IN
        SELECT tablename FROM pg_catalog.pg_tables
         WHERE schemaname = 'public'
           AND tablename NOT IN ('tenant_identity', 'databasechangelog', 'databasechangeloglock')
    LOOP
        EXECUTE format('DROP POLICY IF EXISTS tenant_guard ON public.%I', tenant_table.tablename);
        EXECUTE format('ALTER TABLE public.%I DISABLE ROW LEVEL SECURITY', tenant_table.tablename);
    END LOOP;
END;
$$;
